import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Actions","description":"All the actions a Flow can perform in ApptiveGrid.","frontmatter":{"title":"Actions","description":"All the actions a Flow can perform in ApptiveGrid."},"headers":[],"relativePath":"en/flows/aktionen.md","filePath":"en/flows/aktionen.md","lastUpdated":1787319236000}'),n={name:"en/flows/aktionen.md"};function i(s,e,l,c,p,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h1><p><strong>Actions</strong> are the steps a Flow executes. They live in the editor under the <strong>Actions</strong> tab, with the hint <em>Choose an action to extend your Flow</em>.</p><p>A Flow can contain any number of actions, one after another or branched.</p><div class="tip custom-block"><p class="custom-block-title">Actions marked &quot;Pro&quot;</p><p>Some actions carry the <strong>Pro</strong> label in the editor and are only available on the top plan. They&#39;re marked accordingly below.</p></div><hr><h2 id="working-with-your-own-data" tabindex="-1">Working with your own data <a class="header-anchor" href="#working-with-your-own-data" aria-label="Permalink to &quot;Working with your own data&quot;">​</a></h2><h3 id="create-entry" tabindex="-1">Create entry <a class="header-anchor" href="#create-entry" aria-label="Permalink to &quot;Create entry&quot;">​</a></h3><blockquote><p><em>Creates a new entry</em></p></blockquote><p>Creates an entry in a Grid. You set the field values directly or from previous steps.</p><p><strong>Suited for:</strong> mirroring data from a form into a second Grid, writing log entries, generating tasks.</p><div class="warning custom-block"><p class="custom-block-title">Can trigger its own Flow again</p><p>If an action writes to the same Grid that the <em>New entry</em> trigger listens on, the Flow triggers itself — over and over. Write to a different Grid, or choose a more precise trigger.</p></div><h3 id="update-entry" tabindex="-1">Update entry <a class="header-anchor" href="#update-entry" aria-label="Permalink to &quot;Update entry&quot;">​</a></h3><blockquote><p><em>Update an entry with new values</em></p></blockquote><p>Changes fields of an existing entry — usually the entry from the trigger.</p><p><strong>Suited for:</strong> setting a status, recording a processing timestamp, writing calculated results back.</p><h3 id="load-all-entries" tabindex="-1">Load all entries <a class="header-anchor" href="#load-all-entries" aria-label="Permalink to &quot;Load all entries&quot;">​</a></h3><blockquote><p><em>Load all entries of a Grid</em></p></blockquote><p>Fetches the entries of a Grid into the Flow as a list.</p><p><strong>Suited for:</strong> bulk evaluations, mail merges, recurring reports.</p><div class="tip custom-block"><p class="custom-block-title">Almost always combined with &quot;Parallel&quot;</p><p>A list on its own doesn&#39;t get you far. Only the <a href="/en/flows/router-und-parallel">Parallel</a> helper runs the following steps individually for each entry.</p></div><hr><h2 id="communicating-outward" tabindex="-1">Communicating outward <a class="header-anchor" href="#communicating-outward" aria-label="Permalink to &quot;Communicating outward&quot;">​</a></h2><h3 id="email" tabindex="-1">Email <a class="header-anchor" href="#email" aria-label="Permalink to &quot;Email&quot;">​</a></h3><blockquote><p><em>Send an email</em></p></blockquote><p>Recipient, subject, and body can be freely composed — with fixed text and values from previous steps.</p><p><strong>Suited for:</strong> confirmations, notifications, reminders, forwards.</p><h3 id="http-request" tabindex="-1">HTTP request <a class="header-anchor" href="#http-request" aria-label="Permalink to &quot;HTTP request&quot;">​</a></h3><blockquote><p><em>Send any HTTP request</em></p></blockquote><p>The general-purpose action for anything that doesn&#39;t have a ready-made integration. You specify URL, method, headers, and body yourself.</p><p><strong>Suited for:</strong> your own systems, tools with an open interface, automation services.</p><h3 id="slack-·-ms-teams-·-firebase-cloud-messaging" tabindex="-1">Slack · MS Teams · Firebase Cloud Messaging <a class="header-anchor" href="#slack-·-ms-teams-·-firebase-cloud-messaging" aria-label="Permalink to &quot;Slack · MS Teams · Firebase Cloud Messaging&quot;">​</a></h3><p>Ready-made actions for sending a message to the respective service.</p><h3 id="hubspot" tabindex="-1">HubSpot <a class="header-anchor" href="#hubspot" aria-label="Permalink to &quot;HubSpot&quot;">​</a></h3><p>Creates a contact in the HubSpot CRM.</p><h3 id="magenta-business-sms-·-verify-·-verify-check-—-pro" tabindex="-1">Magenta Business SMS · Verify · Verify Check — <strong>Pro</strong> <a class="header-anchor" href="#magenta-business-sms-·-verify-·-verify-check-—-pro" aria-label="Permalink to &quot;Magenta Business SMS · Verify · Verify Check — **Pro**&quot;">​</a></h3><p>Send SMS and confirm phone numbers via an SMS code. <em>Verify</em> sends the code, <em>Verify Check</em> checks the entered value.</p><p><strong>Suited for:</strong> two-factor confirmation, appointment reminders via SMS.</p><div class="warning custom-block"><p class="custom-block-title">These services require their own credentials</p><p>For Slack, MS Teams, Firebase, HubSpot, and Magenta Business, you need your <strong>own account</strong> with the respective provider. You enter the credentials directly in the Flow step — a webhook URL for Slack and MS Teams, an API key for Firebase, an API token for HubSpot, a key and secret for Magenta.</p><p>Get these <strong>before</strong> you build the Flow. → <a href="/en/integrationen/ueberblick">Integrations at a glance</a></p></div><hr><h2 id="generating-files-and-content" tabindex="-1">Generating files and content <a class="header-anchor" href="#generating-files-and-content" aria-label="Permalink to &quot;Generating files and content&quot;">​</a></h2><h3 id="qr-code" tabindex="-1">QR Code <a class="header-anchor" href="#qr-code" aria-label="Permalink to &quot;QR Code&quot;">​</a></h3><blockquote><p><em>Creates a QR Code</em></p></blockquote><p>Generates a QR code from a given content value.</p><h3 id="pdf-to-text-—-pro" tabindex="-1">PDF to text — <strong>Pro</strong> <a class="header-anchor" href="#pdf-to-text-—-pro" aria-label="Permalink to &quot;PDF to text — **Pro**&quot;">​</a></h3><blockquote><p><em>Convert PDF to text</em></p></blockquote><p>Reads the text content of a PDF.</p><p><strong>Suited for:</strong> processing incoming invoices or forms by machine.</p><h3 id="url-to-pdf-—-pro" tabindex="-1">URL to PDF — <strong>Pro</strong> <a class="header-anchor" href="#url-to-pdf-—-pro" aria-label="Permalink to &quot;URL to PDF — **Pro**&quot;">​</a></h3><blockquote><p><em>Convert website to PDF</em></p></blockquote><p>Generates a PDF from a web address.</p><div class="tip custom-block"><p class="custom-block-title">Generating receipts and confirmations</p><p>Combined with a published <a href="/en/seiten/was-sind-seiten">page</a>, this can be used to generate confirmations and receipts as PDF: open a page with the entry data, convert it to PDF, send it by email.</p></div><h3 id="import-csv-file" tabindex="-1">Import CSV file <a class="header-anchor" href="#import-csv-file" aria-label="Permalink to &quot;Import CSV file&quot;">​</a></h3><blockquote><p><em>Imports a CSV file</em></p></blockquote><p>Reads a CSV file from an address and makes its rows available as a list.</p><h3 id="speech-to-text-—-pro" tabindex="-1">Speech to text — <strong>Pro</strong> <a class="header-anchor" href="#speech-to-text-—-pro" aria-label="Permalink to &quot;Speech to text — **Pro**&quot;">​</a></h3><blockquote><p><em>Convert audio to text</em></p></blockquote><p>Converts an audio recording into text — for example from the <em>Voice recording</em> block of a form.</p><h3 id="document-analyzer-—-pro" tabindex="-1">Document Analyzer — <strong>Pro</strong> <a class="header-anchor" href="#document-analyzer-—-pro" aria-label="Permalink to &quot;Document Analyzer — **Pro**&quot;">​</a></h3><p>Analyzes documents using AI.</p><h3 id="calendar-entry" tabindex="-1">Calendar entry <a class="header-anchor" href="#calendar-entry" aria-label="Permalink to &quot;Calendar entry&quot;">​</a></h3><p>Creates a calendar entry from title, description, and time details.</p><h3 id="datev-payroll-—-pro" tabindex="-1">DATEV Payroll — <strong>Pro</strong> <a class="header-anchor" href="#datev-payroll-—-pro" aria-label="Permalink to &quot;DATEV Payroll — **Pro**&quot;">​</a></h3><blockquote><p><em>Creates a DATEV import file</em></p></blockquote><p>Generates an import file for DATEV Payroll.</p><div class="warning custom-block"><p class="custom-block-title">Credentials required</p><p>This action requires the access key and password for your DATEV account. Keep these ready and handle them confidentially.</p></div><hr><h2 id="working-with-ai" tabindex="-1">Working with AI <a class="header-anchor" href="#working-with-ai" aria-label="Permalink to &quot;Working with AI&quot;">​</a></h2><h3 id="openai-—-pro" tabindex="-1">OpenAI — <strong>Pro</strong> <a class="header-anchor" href="#openai-—-pro" aria-label="Permalink to &quot;OpenAI — **Pro**&quot;">​</a></h3><p>Sends a prompt to ChatGPT and returns the response.</p><p>Inputs: <strong>Prompt</strong> and optionally <strong>Additional instructions</strong>.</p><p><strong>Suited for:</strong> summarizing text, classifying feedback, generating draft replies.</p><div class="tip custom-block"><p class="custom-block-title">No OpenAI contract of your own needed</p><p>Unlike the other integrations, you don&#39;t need your <strong>own</strong> account or API key here. The step runs through ApptiveGrid and is ready to use as soon as your plan includes it.</p></div><div class="danger custom-block"><p class="custom-block-title">Check what data you pass along</p><p>The content of a prompt leaves ApptiveGrid and is sent to an external service. Don&#39;t pass along personal or confidential data without a prior data protection review.</p></div><h3 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h3><blockquote><p><em>Runs JavaScript code</em></p></blockquote><p>Runs your own code when none of the ready-made actions fit. The editor offers:</p><ul><li>A template: <code>const data = input</code> … <code>return data</code></li><li><strong>Generate with AI</strong> — describe in words what the code should do</li><li><strong>Send previous Flow data to AI</strong> — gives the AI the result of the previous step as context</li><li><strong>Restore previous code version</strong></li></ul><p>If generation fails, the editor reports <em>JavaScript could not be generated</em>.</p><div class="tip custom-block"><p class="custom-block-title">The step is free, AI generation is not</p><p><strong>Run JavaScript</strong> is available on every plan — you can always write your own code.</p><p>Only <strong>Generate with AI</strong> is plan-restricted. Without that feature you type the code yourself, which for most transformations is faster anyway than describing it in words.</p></div><hr><h2 id="interacting-with-people" tabindex="-1">Interacting with people <a class="header-anchor" href="#interacting-with-people" aria-label="Permalink to &quot;Interacting with people&quot;">​</a></h2><h3 id="show-page" tabindex="-1">Show page <a class="header-anchor" href="#show-page" aria-label="Permalink to &quot;Show page&quot;">​</a></h3><blockquote><p><em>Displays a page for user interaction</em></p></blockquote><p>Pauses the Flow and shows a person a <a href="/en/seiten/was-sind-seiten">page</a>. Once submitted, the Flow continues.</p><p><strong>Suited for:</strong> approvals, follow-up questions, multi-stage data entry.</p><div class="warning custom-block"><p class="custom-block-title">Don&#39;t confuse it with the trigger of the same name</p><p>There&#39;s also a <strong>trigger</strong> called <em>Show page</em>. That one starts a Flow; this action interrupts one. See <a href="/en/flows/trigger">Trigger</a>.</p></div><p>If a step has no page assigned, it shows:</p><blockquote><p><em>No UI has been set up for this step. If you need a UI, you can add one in the Flow Editor.</em></p></blockquote><h3 id="create-link-to-page" tabindex="-1">Create link to page <a class="header-anchor" href="#create-link-to-page" aria-label="Permalink to &quot;Create link to page&quot;">​</a></h3><blockquote><p><em>Creates a link to a page in the Flow</em></p></blockquote><p>Generates a link to the current run. You can send this link by email so someone can continue at this point later.</p><div class="tip custom-block"><p class="custom-block-title">The path to asynchronous processes</p><p><em>Show page</em> requires someone to be present right now. <em>Create link to page</em> combined with <em>Email</em> also works when the person only has time tomorrow: they receive the link and open it whenever suits them.</p></div><h3 id="prefilled-form-link" tabindex="-1">Prefilled form link <a class="header-anchor" href="#prefilled-form-link" aria-label="Permalink to &quot;Prefilled form link&quot;">​</a></h3><blockquote><p><em>Updates an entry</em></p></blockquote><p>Generates a link to a form that already opens prefilled with the entry, ready for editing.</p><p><strong>Suited for:</strong> requests for corrections, acceptances and declines, data upkeep by external parties.</p><hr><h2 id="nothing-that-fits" tabindex="-1">Nothing that fits? <a class="header-anchor" href="#nothing-that-fits" aria-label="Permalink to &quot;Nothing that fits?&quot;">​</a></h2><p>The editor itself points this out: <em>Nothing fitting found?</em> with the option to submit a request.</p><p>Before that, it&#39;s worth looking at <strong>HTTP request</strong> — it can connect to most services that have an open interface.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/referenz/flow-schritte">Flow steps</a> — quick reference of all steps</li><li><a href="/en/flows/router-und-parallel">Router and Parallel</a></li><li><a href="/en/flows/daten-zwischen-schritten">Data between steps</a></li><li><a href="/en/flows/testen">Testing Flows</a></li><li><a href="/en/integrationen/ueberblick">Integrations at a glance</a></li></ul>',102)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
